import{_ as i,l as r,o as e,c as l,v as t,p,x as n,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"永久收入假说","description":"","frontmatter":{"title":"永久收入假说","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/permanent-income.md","filePath":"econ/permanent-income.md","lastUpdated":1789023840000}'),m={name:"econ/permanent-income.md"};function h(P,a,_,u,E,T){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="永久收入假说" tabindex="-1">永久收入假说 <a class="header-anchor" href="#永久收入假说" aria-label="Permalink to &quot;永久收入假说&quot;">​</a></h1><div class="epigraph"><p>消费跟的是持久资源，不是本周发薪；把暂时收入当成持久的，会把储蓄率看成谜。</p><footer>—— Friedman, A Theory of the Consumption Function, 1957</footer></div><p><a href="/econ/life-cycle-hypothesis">上一课</a>用有限寿命把储蓄写成年龄计划。本课缺口换成 Friedman 的永久收入假说（PIH）：无限期（或很长的视野）下，把收入拆成永久成分与暂时成分，消费主要跟踪前者。不重导 Modigliani 的年龄隆起，也不重写欧拉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LCH 强调退休这一确定的零劳动收入段。Friedman（1957）面对的是另一组事实：短期边际消费倾向低、长期高；农民与小企业主收入更抖但消费更稳。他把实测收入写成 \\(y=y^P+y^T\\)，永久收入 \\(y^P\\) 是人力资本与非人力财富所支撑的可持续消费流。暂时冲击应被储蓄吸收，消费对 \\(y\\) 的回归系数被 \\(y^T\\) 的方差稀释——这是测量误差式的识别，不是新的效用公理。</p><p>Hall（1978）后来把 PIH 写成理性预期下的欧拉：在所列假设下 \\(\\Delta c\\) 不可被已有信息预测。本课先钉 Friedman 的分解；随机游走是同一骨架的预期版本，已在<a href="/econ/consumption-euler">欧拉课</a>出现，此处只引用。</p><p><span class="marginnote">永久不是「永远不变」。利率、寿命、人力资本的新信息会改 \\(y^P\\)。改的是水平，不是把暂时波动一对一写进 \\(c\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>二次效用、完全市场、已知利率时，确定性等价：消费等于永久收入（或年金价值）。储蓄是暂时收入加预防性项（预防性下一课才打开）。经验操作：用职业、教育、过去收入构造 \\(y^P\\) 的代理，看 \\(c\\) 对 \\(y^P\\) 与 \\(y^T\\) 的不同斜率。</p>',9)),(e(),p(c,null,{default:n(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E5%AE%9E%E6%B5%8B%20y%22%5D%20--%3E%20P%5B%22%E6%B0%B8%E4%B9%85%20y%5EP%22%5D%0A%20%20Y%20--%3E%20T%5B%22%E6%9A%82%E6%97%B6%20y%5ET%22%5D%0A%20%20P%20--%3E%20C%5B%22%E6%B6%88%E8%B4%B9%E8%B7%9F%E8%B8%AA%20y%5EP%22%5D%0A%20%20T%20--%3E%20S%5B%22%E5%82%A8%E8%93%84%E5%90%B8%E6%94%B6%20y%5ET%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 LCH 的分工：LCH 给年龄和退休；PIH 给随机或高频收入的永久/暂时切法。两者都反对同期 \\(C=cY\\)。本课不把流动性约束请回来当理论。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是资本市场把暂时资源在时间上摊开。人不是对每周工资作凯恩斯反应，而是对财富的新息作一次水平调整。增长的经济里，永久收入随生产率趋势上移，消费趋势跟随，储蓄率不必趋势性上升——这与简单 LCH 加总可以并存。</p><p>公司金融的股利平滑是近亲：经理把永久盈利当股利，暂时盈利当留存。本课不写股利，以免吞并。也不写限价簿上的成交作为「收入实现」。</p><p>Friedman 的识别是统计的：把 \\(y\\) 对 \\(y^P\\) 的回归稀释写成测量误差，短期 MPC 低、长期高就不再是「人短视」。Hall 把同一想法换成正交性：\\(\\Delta c\\) 对已有信息的回归系数应为零。经验拒绝留给约束与谨慎；本课先把零假设钉在永久成分上。与 LCH 不要争谁更「真」：有限寿命加退休是日历，永久/暂时是随机分解，后课缓冲存量两者都要。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>二次效用关掉预防性储蓄；借贷约束关掉年轻人对 \\(y^P\\) 的提前消费。这两条使 PIH 的过度敏感/过度平滑成为后课对象。股权溢价之谜用总量消费的平滑当证据，与 PIH 的微观平滑不是同一检验：那里缺的是 \\(\\sigma(m)\\)，这里缺的是对 \\(y^T\\) 的保险。</p><p>后课默认：确定性等价 PIH 是基准；打开 \\(u&#39;&#39;&#39;\\gt 0\\) 与约束之后，缓冲存量修正它，而不是退回 \\(C=cY\\)。</p><p>永久成分随新信息跳水平；暂时成分应被储蓄吸收。Hall 把这句话写成正交性。</p><p>与 LCH 近亲但不替代：一个给退休日历，一个给高频收入的切法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Friedman：消费跟踪永久收入，暂时收入进储蓄。</li><li>与 LCH 近亲：一个强调年龄与退休，一个强调永久/暂时分解。</li><li>Hall 的随机游走是 PIH 的理性预期写法，欧拉课已给。</li><li>短期 MPC 低可以是测量误差式稀释，不必是短视。</li><li>确定性等价在下一课被谨慎拆掉。</li><li>出处：Friedman, <em>A Theory of the Consumption Function</em>, 1957；对照 Hall, <em>JPE</em> 1978。</li></ul>',12))])}const B=i(m,[["render",h]]);export{y as __pageData,B as default};
